    var all = parseMcp(github_list_workflow_runs({
        workspace: owner, repository: name, perPage: 30
    }));
    return smRunsFromPayload(all).filter(function (r) {
        return String(r.path || '') === '.github/workflows/machine-sm.yml';
    });
