    test('AC2: an ack-reply failure holds the merge; the retry reads the thread resolved (clean replay)', function () {
        var m = mergeBackstopMod();
        var f = ioFixture({ threads: [belowThread('PRT_N1', nitBody('a nit'), 5)] });
