        var line = m.outcomeLines(run(m, f))[0];
        assert.contains(line, '#42');
        assert.contains(line, 'ack-resolved');
        assert.contains(line, 'wontfix');
        assert.contains(line, 'zero open machine-owned threads');
    });
});

